class WebhookDelivery(BaseModel):
    """
    One attempt to deliver one push, with its outcome.
    """

    model_config = ConfigDict(
        extra="allow",
    )
    id: Annotated[str, Field(description="Encoded identifier of the webhook delivery.")]
    subscription: Annotated[
        str, Field(description="Encoded identifier of the parent subscription.")
    ]
    scheduled_at: Annotated[
        AwareDatetime, Field(description="When this delivery is scheduled to be sent.")
    ]
    attempt_count: Annotated[int, Field(description="Number of delivery attempts made so far.")]
    state: Annotated[
        Literal["PENDING", "SUCCEEDED", "FAILED", "EXHAUSTED", "QUOTA_EXHAUSTED"],
        Field(description="Current state of the delivery."),
    ]
    last_status_code: Annotated[
        int | None, Field(description="HTTP status code returned by the most recent attempt.")
    ]
    last_error: Annotated[
        str, Field(description="Error message from the most recent failed attempt.")
    ]
    response_excerpt: Annotated[
        str, Field(description="Excerpt of the response body returned by the endpoint.")
    ]
    finished_at: Annotated[
        AwareDatetime | None,
        Field(description="When the delivery finished (succeeded or exhausted)."),
    ]
    item_count: Annotated[
        int | None, Field(description="Number of items included in the delivered payload.")
    ]
    sha256: Annotated[str, Field(description="SHA-256 checksum of the delivered payload.")]
    size_bytes: Annotated[int | None, Field(description="Size of the delivered payload in bytes.")]
    created: Annotated[
        AwareDatetime, Field(description="Timestamp set once when the row is first created.")
    ]
    modified: Annotated[
        AwareDatetime, Field(description="Timestamp updated automatically on every save.")
    ]


class WebhookFile(BaseModel):
    """
    One downloadable snapshot file in a manifest push.

    `files` is an array, so read every entry rather than assuming one.
    """

    model_config = ConfigDict(
        extra="allow",
    )
    format: Annotated[
        str,
        Field(
            description="File encoding. Always `ndjson` (newline-delimited JSON, with one row per line)."
        ),
    ]
    expires_at: Annotated[
        int,
        Field(
            description="Unix epoch seconds after which `download_url` stops working. Fetch the file before this time."
        ),
    ]
    sha256: Annotated[
        str, Field(description="Hex SHA-256 of the file body. Use it to verify the download.")
    ]
    size_bytes: Annotated[int, Field(description="Size of the file in bytes.", ge=0)]
    item_count: Annotated[int, Field(description="Number of rows in this file.", ge=0)]
    download_url: Annotated[
        str,
        Field(
            description="Signed, time-limited URL from which to retrieve the file. Expires at `expires_at`."
        ),
    ]


