class SafetyCheckRequest(BaseModel):
    """
    A single safety criterion the AI pipeline evaluates against the creator.

    Only ``type`` is required. The ``extra`` field supplies the label for the
    ``USER_DEFINED_SAFETY_CRITERION`` type and is ignored for the predefined
    types.
    """

    model_config = ConfigDict(
        extra="allow",
    )
    type: Annotated[
        Literal[
            "USER_DEFINED_SAFETY_CRITERION",
            "ADULT_CONTENT",
            "ARMS_AND_AMMUNITION",
            "MISINFORMATION",
            "PROFANITY",
            "POLITICS",
            "DISCLOSURE",
        ],
        Field(
            description="Category of the safety criterion. One of `USER_DEFINED_SAFETY_CRITERION`, `ADULT_CONTENT`, `ARMS_AND_AMMUNITION`, `MISINFORMATION`, `PROFANITY`, `POLITICS`, `DISCLOSURE`.\n\n`DISCLOSURE` looks for explicit sponsorship disclosures (for example `#ad`, a paid partnership, an affiliate commission or a gifted product) in each video's on-screen text, speech transcription, title and caption. It is not scored as a violation: findings are listed under `disclosures` in the result payload, one entry per signal found."
        ),
    ]
    extra: Annotated[
        str | None,
        Field(
            description="Label for `USER_DEFINED_SAFETY_CRITERION`, stored as the criterion's `value`. Ignored for predefined types."
        ),
    ] = None


