class WebhookData(BaseModel):
    """
    The carried content of a push. The populated key depends on `delivery_mode`.

    `manifest` deliveries populate `files` (downloadable snapshot files) and,
    for the content resource, `statistics`. `inline` deliveries populate
    `items` (the rows directly). The unused key is omitted.
    """

    model_config = ConfigDict(
        extra="allow",
    )
    item_count: Annotated[
        int,
        Field(
            description="Total number of rows in this delivery, summed across `files` or equal to the length of `items`.",
            ge=0,
        ),
    ]
    statistics: Annotated[
        Any | None,
        Field(
            description="Aggregate totals over the snapshot, including post count, views, engagement, earned media value, and unique creators. Present only on `content.snapshot`; absent for creator and event pushes."
        ),
    ] = None
    files: Annotated[
        list[WebhookFile] | None,
        Field(
            description="Manifest mode only. The downloadable snapshot files; retrieve each `download_url` and stream the NDJSON rows. Absent in `inline` mode."
        ),
    ] = None
    items: Annotated[
        list[Any] | None,
        Field(
            description="Inline mode only. The delivered rows themselves, in the same shape returned by the matching REST endpoint. Absent in `manifest` mode."
        ),
    ] = None


class WebhookPush(BaseModel):
    """
    The outer payload Zelf POSTs to receivers, uniform across all pushes.

    Top-level fields are delivery metadata and remain identical across
    modes. `data` carries the content; which key inside it is populated
    (`files` or `items`) is determined by `delivery_mode`. `manifest`
    deliveries use `data.files`, while `inline` event pushes use `data.items`.
    """

    model_config = ConfigDict(
        extra="allow",
    )
    id: Annotated[
        str,
        Field(
            description="Unique id of this delivery attempt, stable across retries of the same push."
        ),
    ]
    type: Annotated[
        str,
        Field(
            description="Event type. `<resource>.snapshot` for scheduled snapshots (`content.snapshot`, `creator.snapshot`), or the event name for event pushes (`creator_vetting.completed`)."
        ),
    ]
    subscription_id: Annotated[
        str, Field(description="Id of the subscription that produced this push.")
    ]
    delivered_at: Annotated[
        int, Field(description="Unix epoch seconds at which Zelf sent this push.")
    ]
    livemode: Annotated[
        bool, Field(description="`true` for production data; `false` for test deliveries.")
    ]
    resource: Annotated[
        str | None,
        Field(
            description="Resource the push covers (`content` or `creator`) for snapshots; `null` for event pushes."
        ),
    ] = None
    resource_filters: Annotated[
        Any,
        Field(
            description="The subscription's stored filters that scoped this snapshot, using the same query params as the matching list operation (`content.list` or `creators.list`). Empty for event pushes."
        ),
    ]
    delivery_mode: Annotated[
        Literal["manifest", "inline"],
        Field(
            description="`manifest`: `data.files` holds downloadable snapshot files. `inline`: `data.items` holds the rows directly."
        ),
    ]
    data: Annotated[
        WebhookData,
        Field(
            description="The push payload. See `delivery_mode` for which key inside is populated."
        ),
    ]


